function BattleEndMgr:ResetCameraAndLight()
    if not IsNull(self.goRole) then
        KTool.SafeDelete(self.goRole)
        self.goRole = nil
    end
    if not isNull(self.endTimeline) then
        KTool.SafeDelete(self.endTimeline)
        self.endTimeline = nil
    end
    if not isNull(self.urpBaseCamera) then
        self.urpBaseCamera.enabled = false
        self.urpBaseCamera = nil
    end
    if not IsNull(self.sceneLight) then
        self.sceneLight.enabled = true
    end
    if not IsNull(self.roleLight) then
        self.roleLight.enabled = false
    end
    if self.coCatIdle then
        cs_coroutine.stop(self.coCatIdle)
    end
    self:SetCBEnabledState(true)
end
