function BattleEndMgr:BattleEndShow()
    local roleData = self:GetFinalDamageRoleData()
    if not roleData then return end
    local skinId = UIBattlingDataMgr:GetCharacterSkinIdById(BattleInfo.myCamp, roleData.id)
    if isNull(skinId) then return end
    
    ---@type CardSkinVo
    local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
    if isNull(cardSkinVo) then return end

    if cardSkinVo.endTimeline == nil then
        -- 没填结算timeline，用旧的角色模型表演
        self:SwitchBattleEndRoleShow(cardSkinVo)
    else        
        local showType = cardSkinVo.endCtrl
        if showType == 0 then
            -- 随机播放
            local random = Mathf.Random(0,1)
            -- random = 1
            if random == 0 then
                self:SwitchBattleEndRoleShow(cardSkinVo)
            elseif random == 1 then
                self:BattleEndTimelineShow(cardSkinVo.endTimeline)
            end
        elseif showType == 1 then
            self:BattleEndTimelineShow(cardSkinVo.endTimeline)
        elseif showType == 2 then
            self:SwitchBattleEndRoleShow(cardSkinVo)
        end
    end

    -- 等待timeline场景加载完成
    while isNotNull(self.coShowRole) do
        CoYield()
    end
end

function BattleEndMgr:SwitchBattleEndRoleShow(cardskinVo)
    if cardskinVo.endTimeline50 == nil then
        -- 标准人型结算
        self:BattleEndRoleShow()
    else
        -- 50皮人型结算
        self:BattleEndRoleShow50(cardskinVo.endTimeline50)
    end
end

