function BattleEndMgr:BattleEndRoleShow()
    --- Camera
    local goBattleEndCamera = GameObject.Find(RootEndCamera)
    local battleEndCamera
    if not IsNull(goBattleEndCamera) then
        battleEndCamera = goBattleEndCamera:GetComponent(typeof(Camera))
        if not IsNull(battleEndCamera) then
            battleEndCamera.enabled = false
        end
        self.urpBaseCamera = goBattleEndCamera:GetComponent(typeof(URPBaseCamera))
    end
    local goRootRole = GameObject.Find(RootRolePosition) -- RolePos
    if IsNull(battleEndCamera) or IsNull(goRootRole) then return end
    local roleData = self:GetFinalDamageRoleData()
    if not roleData then return end
    local skinId = UIBattlingDataMgr:GetCharacterSkinIdById(BattleInfo.myCamp, roleData.id)
    local cardId = UIBattlingDataMgr:GetCharacterRefIdById(BattleInfo.myCamp, roleData.id)
    self.coShowRole = cs_coroutine.start(function()
        cs_coroutine.yield_return(self:LoadRoleModel(cardId, skinId, goRootRole, roleData.weaponUnlocked))
        local cat = BattleViewMgr.unitCat
        if not IsNull(cat) then
            cat:StopCo()
            cat:HideLoopFXNode()
            local rolePosition = self.goRole.transform.localPosition
            KTool.SetParent(cat.gameObject, goRootRole.gameObject)
            local sceneVo = checkTable(BattleViewMgr.sceneVo)
            local dataCatEndCam = checkTable(sceneVo.catEndCam)
            --print("->dataCatEndCam", table.dump(sceneVo), table.dump(checkTable(dataCatEndCam)))
            local offSetCatPosition = dataCatEndCam.position
            local catRotation = dataCatEndCam.rotation
            local catPosition = Vector3.New(rolePosition.x + offSetCatPosition.x, offSetCatPosition.y, rolePosition.z + offSetCatPosition.z)
            local transCat = cat.transform
            transCat.localPosition = catPosition
            transCat.transform.localRotation = catRotation
            KTool.SetActive(cat.gameObject, true)
            self.coCatIdle = cs_coroutine.start(function() 
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(2))
                cat:PlayAnimation("cat_idle2", true, 0)
                self.coCatIdle = nil
            end)
        end
        if not IsNull(self.urpBaseCamera)  then
            self:SetCBEnabledState(false)
            self.urpBaseCamera.enabled = true
        end
        local goSceneLight = GameObject.Find(SceneLight)
        if not IsNull(goSceneLight) then
            self.sceneLight = goSceneLight:GetComponent(typeof(Light))
            if not IsNull(self.sceneLight) then
                self.sceneLight.enabled = false
            end
        end
        local goRoleLight = GameObject.Find(RootEndLight)
        if not IsNull(goRoleLight) then
            self.roleLight = goRoleLight:GetComponent(typeof(Light))
            if not IsNull(self.roleLight) then
                self.roleLight.enabled = true
            end
        end

        local ccd = URPCameraController.mainCamera.gameObject:GetComponent(typeof(CameraCustomData))
        if isNotNull(ccd) then
            ccd.Role = CameraCustomData.RoleSettingEnum.HighQuality
            ccd.Fur = CameraCustomData.RoleFurSettingEnum.HighQuality
        end

        self.coShowRole = nil
    end)
end

--- 加载并播放战斗结算timeline
---@param timelineName any
function BattleEndMgr:BattleEndTimelineShow(timelineName)
    local timelineRoot = GameObject.Find(RootRolePosition) -- RolePos
    if IsNull(timelineRoot) then return end
    
    local path = string.format('Arts/Prefab_cat/Prefab_cat_timeline/%s.prefab', timelineName)
    self.coShowRole = cs_coroutine.start(function ()
        local loader = ResourceModule.LoadBundleAsync(path, nil, true)
        while not loader.IsSuccess do
            cs_coroutine.yield_return()
        end
        if not loader.IsError then
            local ccd = URPCameraController.mainCamera.gameObject:GetComponent(typeof(CameraCustomData))
            if isNotNull(ccd) then
                ccd.Role = CameraCustomData.RoleSettingEnum.HighQuality
                ccd.Fur = CameraCustomData.RoleFurSettingEnum.HighQuality
            end
            self:SetCinemachineBlendMode()
            self.endTimeline = loader:Instantiate()
            self:SetCatEndTimelineLocation(self.endTimeline)
            local director = KTool.GetComponent(self.endTimeline, typeof(PlayableDirector))
            local loopStartTime = self:GetMarkerTime(director, "HomeRoleIdle")
            self:AddSignalReceiver(self.endTimeline, "Timeline/TimeLineSignal/HomeRoleTrigger.signal", function ()
                director.time = loopStartTime
            end)
            self.endTimeline:AddComponent(typeof(CS.CustomLightDirRelativeCamera))
            self.endTimelineLoopStartTime = loopStartTime
            director:Play()
        end
        loader:Release()
        loader = nil
        self.coShowRole = nil
    end)
end

--- 给物体添加指定timeline信号的回调
---@param go any
---@param signalPath any
---@param callback any
function BattleEndMgr:AddSignalReceiver(go, signalPath, callback)
    local signalReceiver = KTool.GetOrAddComponent(go, typeof(SignalReceiver))
    ResourceModule.LoadBundleAsync(signalPath, function(loader, ok, resultObject)
        if ok then
            loader:Retain(signalReceiver)
            local event = CS.UnityEngine.Events.UnityEvent();
            event:AddListener(function()
                callback()
            end)
            signalReceiver:AddReaction(loader.ResultObject, event)
        end
        loader:Release()
    end)
end

--- 获取timeline里面指定名字marker的time
---@param playableDirector any
---@param markerName any
function BattleEndMgr:GetMarkerTime(playableDirector, markerName)
    local markerTrack = playableDirector.playableAsset.markerTrack

    local markerCount = markerTrack:GetMarkerCount()
    for i = 0, markerCount - 1, 1 do
        local marker = markerTrack:GetMarker(i)
        if string.contains(marker.asset.name, markerName) then
            return marker.time
        end
    end
end

