function BattleEndMgr:LoadRoleModel(cardId, skinId, roleRoot, weaponUnlocked)
    ---@type CardSkinVo
    local cardSkinVo = cardConfMgr:GetCardSkinBySkinId(skinId)
    if isNull(cardSkinVo) then return end
    local poolName = string.format("Arts/Prefab_lobby/%s.prefab", cardSkinVo.lobbyMode)
    local loader = ResourceModule.LoadBundleAsync(poolName, nil, true)
    while not loader.IsCompleted do
        cs_coroutine.yield_return()
    end
    if loader.IsSuccess then
        xTry(function()
            ---@type UnityEngine.GameObject
            -- local go = KTool.Instantiate(roleRoot.gameObject, loader.ResultObject, false)
            local go = loader:Instantiate(roleRoot.transform, false)
            self.goRole = go
            local cardPositionVo = cardConfMgr:GetCardPosByCardId(cardId, skinId)
            local rolePos = not isNull(cardPositionVo) and cardPositionVo.battleEndRolePos or Vector3.New(0, 0, 0)
            local roleScale = not isNull(cardPositionVo) and cardPositionVo.scale or 1
            go.transform.localPosition = rolePos
            go.transform.localRotation = Quaternion.Euler(0, 0, 0)
            go.transform.localScale = Vector3.one * roleScale
            
            local lightDir = KTool.GetOrAddComponent(go, typeof(CS.CustomLightDirRelativeCamera))
            if not isNull(lightDir) then
                lightDir.CustomLightDirection = Vector3.New(25, 17, 0)
            end

            local faceForwards = go:GetComponentsInChildren(typeof(CS.FaceForward))
            for i = 1, faceForwards.Length do
                local faceForward = faceForwards[i - 1]
                if not isNull(faceForward.TargetTransform) then
                    KTool.GetOrAddComponent(faceForward.gameObject, typeof(CS.CustomFaceLightDir))
                end
            end

            -- 专武特效
            if not isNull(weaponUnlocked) then
                local comp = self.goRole:GetComponentInChildren(typeof(CS.Game.Native.Common.ExclusiveWeaponController))
                if not isNull(comp) then
                    local maxLv = CardConfMgr:GetInstance():GetMaxCardExclusiveWeaponLv(cardId)
                    comp.IsShow = weaponUnlocked >= maxLv and maxLv > 0
                end
            end
            
            KTool.SetActive(go, true)
        end)
    end
    -- self.loader = loader
    loader:Release()
end

---GetFinalDamageRoleData
---获取展示角色的数据
function BattleEndMgr:GetFinalDamageRoleData()
    local roleId = UIBattlingCtrlMgr:GetInstance():GetDamagingCharactorBattleFieldId()
    local isPlayerTeam = UIBattlingDataMgr:CheckIdInCampTeam(BattleInfo.myCamp, roleId)  --是否是玩家队伍
    local characterData = UIBattlingDataMgr:GetCharactorDataById(roleId)
    if IsNull(characterData) or not isPlayerTeam then
        characterData = UIBattlingDataMgr:GetEnterVoiceCharactorData()
    end
    return characterData
end

