---SwitchBattleEnd
function BattleEndMgr:SwitchBattleEnd(args)
    if BattleInfo and BattleInfo.gameMode == Constants.GameMode.PVP then
        if BattleInfo.pvpMode == Constants.PVPMode.Arena then
            local next = FightPreWarMgr:GetInstance():PVPBattleDataHandle(BattleInfo.pvpMode, args)
            if next then
                cs_coroutine.start(function()
                    local dialogs = UIModule.CurrentScreen.dialogs
                    for i, dialog in pairs(dialogs) do
                        UIModule.CloseDialog(dialog)
                    end
                    local gameMode = BattleInfo.gameMode
                    local pvpMode = BattleInfo.pvpMode
                    BattleInfo:Dispose()
                    BattleInfo = nil
                    local BI = import("Game.BattleView.Core.BattleInfo")
                    local outData = {}
                    cs_coroutine.yield_return(BI.GetInitData(Constants.GameMode.PVP, outData))
                    BattleInfo = BI.New(gameMode, outData.playMode, pvpMode, outData.inputMode, outData.initData, outData.recordData)
                    --local d = BattleInfo.initData
                    BattleViewMgr:RestartBattle(nil, nil, BattleViewMgr.waitForStart)
                end)
            else
                self:FriendBattleBattleEnd(args)
            end
        elseif BattleInfo.pvpMode == Constants.PVPMode.Friend then
            self:FriendBattleBattleEnd(args)
        elseif BattleInfo.pvpMode == Constants.PVPMode.LadderCompetion then
            self:OnlineBattleEnd(args)
        else
            self:FriendBattleBattleEnd(args)
        end
    elseif BattleInfo and BattleInfo.playMode == Constants.PlayMode.Replay then
        if not IsNull(LadderStruggleMgr) and LadderStruggleMgr:IsLadderStruggle() then
            LadderStruggleMgr:LadderStruggleBattleEnd(args)
        else
            GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome) 
        end
    elseif BattleInfo and BattleInfo.isSimulator then
        self:FriendBattleBattleEnd(args)
    elseif BattleInfo and BattleInfo.gameMode == Constants.GameMode.OnlinePVE then
        self:OnlineBattleEnd(args)
    end
end

function BattleEndMgr:AnnihilationBattleEnd(args)
    if checkNumber(args.isPassed) == 1 then
        local type = GoodsUtils.GetIdType(args.questId, Constants.IDArea.Quests)
        if type == Constants.IDType.QuestAnnihilation then
            args.isInvited = BattleInfo:IsInvited()     -- 获取我自己是房主还是成员
            local ActionComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
            ActionComponent:UpdateAnnihilationQuestInfo(args)
        end
    end

    -- 翻牌奖励数据
    local flipCardData
    local mainNeedFlip = isNotNull(args.mainIsFlip) and (checkNumber(args.mainIsFlip) == 1) or false
    local subNeedFlip = isNotNull(args.subIsFlip) and (checkNumber(args.subIsFlip) == 1) or false
    if mainNeedFlip or subNeedFlip then
        flipCardData = {
            mainNeedFlip = args.mainIsFlip,
            subNeedFlip = args.subIsFlip,
            rewards = args.flipCardRewards,
            rewardsList = args.flipCardRewardsList,
        }
    end

    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIBattleEndDialog, parameters = {
        questId = checkNumber(args.questId),
        isPassed = checkNumber(args.isPassed),
        response = args,
        callback = function()
            ---@type Engine.UI.UIRaycastBlocker
            local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
            blocker:AddCondition("GOHomeBlocker")
            return cs_coroutine.start(function()
                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome, hasExcluded = false }, nil, Constants.LoadingType.MainHome)
                blocker:RemoveCondition("GOHomeBlocker")
            end)
        end,
        playerOldLv = args.playerOldLevel,
        cardExpInfo = args.cardExpInfo,
        flipCardData = flipCardData,
    } })
end

