--- 联机结算
---@param resultData any
function BattleEndMgr:OnlineBattleEnd(args)
    if self.onlineResultReceived then
        -- 已经收到4013，直接结算（队友先发了4012，服务器结算完毕下发4013。所以有可能还没发4012就先收到4013
        BattleViewMgr.netMgr:Log2File("提前收到4013，跳过请求4013")
        print("提前收到4013，跳过请求4013")
        self:ShowOnlineBattleEnd(self.onlineResult)
    else
        -- 没收到4013，发送4012请求结算
        BattleViewMgr.netMgr:Log2File("未收到4013，请求4013")
        print("未收到4013，请求4013")
        BattleViewMgr.netMgr:Send(BattleViewMgr.netMgr.SendPackageIds.SendGameEnd, {isPassed = args.isWin and 1 or 0, recordData = args.recordData})
        BattleViewMgr:DebugTestNetwork()
        -- 等待服务器下发结算数据
        local loopNumMax = 20
        local loopIndex = 0
        local getResult = false
        local timer = 0
        local overTime = 3
        local interval = 0.2

        cs_coroutine.start(function()
            -- GameUtils.Toast(localize("等待结算结果"))
            GameUtils.BeforeRequest()
            -- 开启一个loopNumMax次数的循环，每次循环内执行一个overTime的等待4013
            -- 如果超过overtime还没收到4013，会发送一个http请求结算结果。如果http说服务器确实还没结算，那么再进入下一个loop继续等
            while loopIndex < loopNumMax and getResult == false do
                timer = 0
                while timer < overTime and getResult == false do
                    if isNotNull(self.onlineResult) then
                        if getResult == true then break end
                        getResult = true
                        BattleViewMgr.netMgr:Log2File("收到4013，结算")
                        print("收到4013，结算")
                        self:ShowOnlineBattleEnd(self.onlineResult)
                        break
                    end
                    coroutine.yield(WaitForSecondsRealtime(interval))
                    timer = timer + interval
                end
                -- 如果等待超时，尝试用http请求结算
                if not getResult then
                    BattleViewMgr.netMgr:Log2File("等待4013超时，请求http结算 loopIndex:" .. tostring(loopIndex))
                    print("等待4013超时，请求http结算 loopIndex:" .. tostring(loopIndex))
                    GameUtils.Request(Interfaces.OverseaRegionalBossGetSettleResult, {roomId = BattleViewMgr.roomId}, function(request, response)
                        if checkNumber(response.errCode) ~= 0 then return end
                        local data = response.data.result
                        if table.count(data) == 0 then
                            print("服务器未结算，继续等待")
                            return 
                        end   -- 服务器还未结算，继续等
                        if getResult == true then return end
                        getResult = true
                        self:ShowOnlineBattleEnd(data)
                    end)
                else
                    break
                end
                coroutine.yield(WaitForSecondsRealtime(interval))
                loopIndex = loopIndex + 1
            end
            GameUtils.AfterRequest()
            -- 超时没有收到4013，走通用结算
            if loopIndex >= loopNumMax then
                self:FriendBattleBattleEnd(args)
            end
        end)
    end    
end

function BattleEndMgr:ShowOnlineBattleEnd(data)
    print("[结算] Online结算数据 ", table.dump(data, nil, 3))
    BattleViewMgr.netMgr:Disconnect()
    GameUtils.AfterRequest()
    -- 检查是否有服务器报错
    if isSet(data, "errCode") then
        local code = checkNumber(data.errCode)
        if code == 102 then
            -- 战斗验证未通过
            data.errMsg = localize("由于不可抗力, 操作失败了, 请联系客服").." T_T"
            local callback = function()
                Events.Broadcast(Constants.EventNames.UIBattlingBackToFightReady)
                local UIBattlingCtrlMgr = import("Game.UI.UIBattling.UIBattlingCtrlMgr")
                UIBattlingCtrlMgr:GetInstance():BackToFightReadyCommon()
            end
            GameUtils.SecondConfirm(data.errMsg, callback, callback)
            return
        end
    end

    -- 更新玩家奖励
    FightPreWarMgr:UpdateRewards(data)
    -- 更新玩家经验
    data.playerOldLevel = FightPreWarMgr:UpdatePlayerExp(data)
    -- 更新卡牌经验
    data.cardExpInfo = FightPreWarMgr:UpdateCardExp(data)

    if BattleInfo:IsPVP() then
        -- 天梯
        self:LadderCompetionBattleEnd({isWin = data.matchResult == 1, response = data})
    else
        -- 歼灭战
        self:AnnihilationBattleEnd(data)
    end
end

