function BattleEndMgr:GetRewardsList(showData)
    local rewardsList = {}
    if IsNull(showData) or (not isSet(showData, "response")) then return rewardsList end
    if isSet(showData.response, "rewards") and table.count(showData.response.rewards) > 0 then
