function BattleEndMgr:HandleRewardSort(rewardsPara)
    local list_Ids = {
        [411001] = 1,
        [419002] = 1,
    }
    local rewardsList = checkTable(rewardsPara)
    local rewardSpecial = {}
    local rewardCommon = {}
    for i, goodsData in pairs(rewardsList) do
        local goodsId = checkNumber(goodsData.goodsId)
        local list2Insert = isNull(list_Ids[goodsId]) and rewardCommon or rewardSpecial
        table.insert(list2Insert, goodsData)
    end
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local _functionSort = function(a, b, fieldNames)
        local fieldNameCount = #fieldNames
        local loopTimes = fieldNameCount
        local goodsVoA = goodsConfMgr:GetGoodsVoById(a.goodsId)
        local goodsVoB = goodsConfMgr:GetGoodsVoById(b.goodsId)
        for i = 1, loopTimes  do
            local fieldName = fieldNames[i]
            if isNull(goodsVoA) or isNull(goodsVoB) then
                return true
            end
            local aFiled, bFiled = checkNumber(goodsVoA[fieldName]), checkNumber(goodsVoB[fieldName])
            if aFiled ~= bFiled or i == loopTimes then
                return aFiled > bFiled
            end
        end
    end
    
    local fieldNames = { "quality", "id" }
    table.sort(rewardCommon, function(a, b)
        return _functionSort(a, b, fieldNames)
    end)
    return table.link(checkTable(rewardSpecial), checkTable(rewardCommon))
end


---GetSpecialQuestRewards
---获取特殊关卡的特殊奖励
---@param showData table 服务器返回数据
---@param list table 奖励列表
function BattleEndMgr:GetSpecialQuestRewards(showData, list)
    local questId = self.questId
    local questType = checkNumber(GoodsUtils.GetIdType(questId, Constants.IDArea.Quests))
    if questType == Constants.IDType.QuestMaze and checkNumber(showData.response.coin) > 0 then
        local t = {
            goodsId = Constants.Currency.MazeCurrency,
            num = checkNumber(showData.response.coin)
        }
        table.insert(list, t)
    end
    if (questType == Constants.IDType.QuestCoinsCopy
            or questType == Constants.IDType.QuestExpCopy
            or questType == Constants.IDType.QuestUpStarCopy)
            and checkNumber(showData.response.energyPoint) > 0 then
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(showData.questId)
        --- 获取物品 Id
        local _getItemID = function(type)
            local dailyTypeVo = CfUtils.GetCfVo(AutoIds.IdSetting310, "DailyTypeVo", type)
            return dailyTypeVo.energyPointItem
        end
        local itemId = _getItemID(vo.type)
        local valueItem = vo.energy or -999
        table.insert(list, {
            goodsId = itemId,
            num = valueItem,
        })
    end
end

