---DataSort
---游戏物品数据排序
---@param target table
---@param low integer
---@param high integer
function BattleEndMgr:DataSort(target, low, high)
    local t = low or 1
    local r = high or #target
    local temp = target[t]
    if low < high then
        while (t < r) do
            while (self:CheckGoodsIdForDateSort(target[r].goodsId) >= self:CheckGoodsIdForDateSort(temp.goodsId) and t < r) do
                r = r - 1
            end
            target[t] = target[r]
            while (self:CheckGoodsIdForDateSort(target[t].goodsId) <= self:CheckGoodsIdForDateSort(temp.goodsId) and t < r) do
                t = t + 1
            end
            target[r] = target[t]
        end
        target[t] = temp
        self:DataSort(target, low, t - 1)
        self:DataSort(target, r + 1, high)
    end
end

---CheckGoodsIdForDateSort
---返回物品类型ID
---@param goodsId integer @ 物品Id
function BattleEndMgr:CheckGoodsIdForDateSort(goodsId)
    local idType = GoodsUtils.GetIdType(goodsId)
    local typeList = {
        [Constants.IDType.CharacterCard] = 1, -- 角色卡
        [Constants.IDType.Equipment] = 2, -- 装备
    }
    --- 3 游戏道具
    return typeList[idType] or 3
end

