function BattleEndMgr:GetPlayerEXPChange()
    local _playerEXP_GoodId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 15).num
    if IsNull(UIBattlingDataMgr) then return end
    local playerExpBeforeBattleEnd = UIBattlingDataMgr:GetValuePlayExpBeforeBattleEnd()
    if isNull(self.showData) or (not isSet(self.showData, "response")) or (not isSet(self.showData.response, "mainExp"))  then return end
    if IsNull(playerExpBeforeBattleEnd) or checkInt(playerExpBeforeBattleEnd) >= checkInt(self.showData.response.mainExp) then return end
    local numEXP = checkInt(clone(self.showData.response.mainExp)) - checkInt(playerExpBeforeBattleEnd)
    -- print("~___BattleEndPlayerExp：",self.showData.response.mainExp ,playerExpBeforeBattleEnd)
    return { goodsId = _playerEXP_GoodId, num = numEXP }
end

