function BattleEndMgr:IsWholeRobTeam()
    local questId = self.questId
    local levelVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if isNull(levelVo) then
        -- print("[结算] 没有找到关卡数据 ", questId)
        return false
    end
    local teamId = levelVo.petLineup
    if isNull(teamId) or Tools.isNullKey(teamId) then return false end
    local teamVo = CfUtils.GetCfVo(AutoIds.IdSetting721, "BattleHelperTeamVo", teamId)
    if isNull(teamVo) then return false end
    local station = teamVo.Station
    if isNull(station) or Tools.isNullKey(station) then return false end
    local listPos = CfUtils.Split(checkString(station))
    if isNull(listPos) or isNull(UIBattlingDataMgr.playerTeam) then return false end
    return #listPos >= #UIBattlingDataMgr.playerTeam
end
 
function BattleEndMgr:GetJump2CultivateCardDJ()
    local questId = self.questId
    local playerTeam = UIBattlingDataMgr.playerTeam
    local levelVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if isNull(levelVo) then
        -- print("[结算] 没有找到关卡数据 ", questId)
        return nil
    end
    -- print("[结算] GetJump2CultivateCardDJ ", table.dump(playerTeam, nil, 3), debug.traceback)
    for i = 1, #playerTeam do
        local roleData = playerTeam[i]
        if UIBattlingTools.IsMyPlayerId(roleData.playerId) then
            local cardId = roleData.cardId
            -- print("[结算] 前往养成 ", self.questId, levelVo, cardId)
            local robVo = BattleHelperConfMgr:GetInstance():GetMainLevelHelper(levelVo.petLineup, cardId)
            if isNull(robVo) then
                ---@type CardComponent
                local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local playerCardId = roleData.playerCardId
                ---@type CardDojo
                local cardDojo = cardComponent:GetCardById(playerCardId)
                -- print("->BattleEndMgr:GetJump2CultivateCardDJ:", robVo, playerCardId, cardDojo)
                return not isTable(cardDojo) and nil or cardDojo
            end
        end
    end
end

function BattleEndMgr:ResetSceneCamera()
    local _camera
    local cameras = Camera.allCameras;
    for i = 1, cameras.Length do
        local cam = cameras[i - 1]
        if cam.gameObject.name == RootSceneCamera and cam.gameObject.tag ~= "MainCamera" then
            _camera = cam
        end
    end
    if not IsNull(_camera) then
        local _urpBaseCamera = _camera:GetComponent(typeof(URPBaseCamera))
        if  not IsNull(_urpBaseCamera) then
            _urpBaseCamera.enabled = true
            _urpBaseCamera.enabled = false
        end
    end
end

function BattleEndMgr:ClosePopDialog()
    return cs_coroutine.start(function() 
        UIBattlingTools.CloseSecondConfirm()
        UIBattlingTools.CloseCommonTipsBoard()
        local listNeed2Close = {
            [Constants.UITypeIds.UIBattlingCharactorInfoDialog] = 1,
            [Constants.UITypeIds.UIBattlingBackToFightReadyDialog] = 1,
            [Constants.UITypeIds.UIGamePlayGuideBookDialog] = 1,
            [Constants.UITypeIds.UIBattlingAttributeCircleDialog] = 1,
            [Constants.UITypeIds.OverseaChatMainDialog] = 1,
            [Constants.UITypeIds.Player2DMainDialog] = 1,
        }
        local coWait = CoWait.Start()
        local wait = false
        for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
            if not isNull(v) then
                local dialogId = checkNumber(v.Argument.id)
                if not IsNull(listNeed2Close[dialogId]) then
                    local co = UIModule.CloseDialog(v)
                    if not isNull(co)
                    and not co.IsFinish then
                        wait = true
                        coWait:Coroutine(co)
                    end
                end
            end
        end
        while not coWait.IsFinish and wait do
            cs_coroutine.yield_return()
        end
    end)
end

