--- 激活隐藏结算场景（因为场景里有一些零散在外面的比如背景特效，高度雾这种东西，所以除了不需要管的，其他全部执行setactive）
---@param state any
function BattleEndMgr:SetActiveBattleEndScene(state)
    if BattleViewMgr == nil then
        return
    end
    if self and checkBool(self.battleSceneActiveState) == state then
        return
    end
    local scene = BattleViewMgr.nowScene
    if isNull(scene) then
        return
    end
    self.battleSceneActiveState = state
    local rootGameObjects = scene:GetRootGameObjects()
    local length = rootGameObjects.Length
    for i = 0, length - 1, 1 do
        local go = rootGameObjects[i]
        if not table.isContain(ExcludeObjs, go.name) then
            KTool.SetActive(go, state)
        end
    end
end

function BattleEndMgr:SetActiveLowDiscShadow(state)
    CS.FuntoyRenderFeature.isOpenPlaneShadow = state
end

